[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellSource — Expert Health Guidance You Can Trust</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ═══════════════════════════════════════════
   WellSource Design System — OKLCH Palette
   ═══════════════════════════════════════════ */
:root {
  /* Primary — Teal */
  --color-primary:        oklch(52% 0.118 200);
  --color-primary-hover:  oklch(46% 0.105 200);
  --color-primary-light:  oklch(72% 0.06 195);
  --color-primary-pale:   oklch(92% 0.025 195);

  /* Accent — Warm amber/coral */
  --color-accent:         oklch(66% 0.145 45);
  --color-accent-hover:   oklch(60% 0.13 43);
  --color-accent-light:   oklch(88% 0.06 50);

  /* Neutrals */
  --color-text:           oklch(18% 0.008 260);
  --color-text-secondary: oklch(48% 0.01 260);
  --color-text-muted:     oklch(65% 0.01 260);
  --color-bg:             oklch(100% 0 0);
  --color-bg-warm:        oklch(97% 0.008 90);
  --color-bg-cool:        oklch(97% 0.012 210);
  --color-bg-teal:        oklch(94% 0.03 200);
  --color-border:         oklch(90% 0.01 240);
  --color-border-light:   oklch(94% 0.008 240);

  /* Shadows */
  --shadow-sm:  0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md:  0 4px 12px oklch(0% 0 0 / 0.08);
  --shadow-lg:  0 8px 30px oklch(0% 0 0 / 0.10);
  --shadow-xl:  0 20px 60px oklch(0% 0 0 / 0.12);

  /* Spacing scale — 8px base */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  16px;
  --space-4:  24px;
  --space-5:  32px;
  --space-6:  48px;
  --space-7:  64px;
  --space-8:  96px;

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --text-xs:   0.75rem;
  --text-sm:   0.875rem;
  --text-base: 1rem;
  --text-lg:   1.125rem;
  --text-xl:   1.25rem;
  --text-2xl:  1.5rem;
  --text-3xl:  1.875rem;
  --text-4xl:  2.25rem;
  --text-5xl:  3rem;

  /* Radii */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Layout */
  --max-width: 1200px;
  --header-height: 64px;

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
}

/* ═══════════════════════════════════════════
   Reset & Base
   ═══════════════════════════════════════════ */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: color var(--duration-fast) var(--ease-out);
}
a:hover { color: var(--color-primary-hover); }

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

input {
  font-family: inherit;
  font-size: inherit;
}

ul, ol { list-style: none; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

/* ═══════════════════════════════════════════
   Typography
   ═══════════════════════════════════════════ */
.section-label {
  font-size: var(--text-sm);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-primary);
}

.section-heading {
  font-size: var(--text-4xl);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.section-subheading {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  line-height: 1.6;
  max-width: 600px;
}

/* ═══════════════════════════════════════════
   Buttons
   ═══════════════════════════════════════════ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 12px 24px;
  font-size: var(--text-base);
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: #fff;
}
.btn-primary:hover {
  background: var(--color-primary-hover);
  color: #fff;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-text);
}
.btn-accent:hover {
  background: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
  background: transparent;
}
.btn-outline:hover {
  background: var(--color-primary);
  color: #fff;
}

.btn-ghost {
  color: var(--color-text-secondary);
  font-weight: 500;
}
.btn-ghost:hover {
  color: var(--color-primary);
  background: var(--color-primary-pale);
}

.btn-sm {
  padding: 8px 16px;
  font-size: var(--text-sm);
}

.btn-lg {
  padding: 16px 32px;
  font-size: var(--text-lg);
}

/* ═══════════════════════════════════════════
   Header
   ═══════════════════════════════════════════ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: oklch(100% 0 0 / 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border-light);
}

.header-inner {
  display: flex;
  align-items: center;
  height: var(--header-height);
  gap: var(--space-5);
}

.header-logo {
  font-size: var(--text-2xl);
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -0.02em;
  flex-shrink: 0;
}
.header-logo span {
  color: var(--color-text);
  font-weight: 600;
}

/* Main Nav */
.main-nav {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  height: 100%;
}

.nav-item {
  position: relative;
  height: 100%;
  display: flex;
  align-items: center;
}

.nav-trigger {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  border-radius: var(--radius-md);
  transition: all var(--duration-fast) var(--ease-out);
  height: 40px;
}
.nav-trigger:hover,
.nav-item.active .nav-trigger {
  background: var(--color-primary-pale);
  color: var(--color-primary);
}
.nav-trigger .chevron {
  width: 16px;
  height: 16px;
  transition: transform var(--duration-normal) var(--ease-out);
}
.nav-item.active .nav-trigger .chevron {
  transform: rotate(180deg);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(8px);
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: var(--space-5);
  min-width: 560px;
  opacity: 0;
  visibility: hidden;
  transition: all var(--duration-normal) var(--ease-out);
}
.nav-item.active .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-1);
}

.mega-menu a {
  display: block;
  padding: 8px 14px;
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text);
  border-radius: var(--radius-sm);
  transition: all var(--duration-fast) var(--ease-out);
}
.mega-menu a:hover {
  background: var(--color-primary-pale);
  color: var(--color-primary);
}

.mega-menu-section-title {
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--color-text-muted);
  padding: 10px 14px 6px;
}

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-left: auto;
  flex-shrink: 0;
}

/* Mobile nav */
.mobile-menu-btn {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  color: var(--color-text);
  font-size: 24px;
}

.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  top: var(--header-height);
  background: var(--color-bg);
  z-index: 99;
  overflow-y: auto;
  padding: var(--space-4);
}

.mobile-nav.open {
  display: block;
}

.mobile-nav-group {
  border-bottom: 1px solid var(--color-border-light);
  padding: var(--space-3) 0;
}

.mobile-nav-group-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 14px 0;
  font-size: var(--text-lg);
  font-weight: 700;
  color: var(--color-text);
}

.mobile-nav-sublinks {
  display: none;
  padding: 0 0 var(--space-3) var(--space-3);
}
.mobile-nav-group.open .mobile-nav-sublinks {
  display: block;
}

.mobile-nav-sublinks a {
  display: block;
  padding: 10px 0;
  font-size: var(--text-base);
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
}
.mobile-nav-sublinks a:hover {
  color: var(--color-primary);
}

/* ═══════════════════════════════════════════
   Credibility Ticker
   ═══════════════════════════════════════════ */
.credibility-ticker {
  background: var(--color-primary);
  color: #fff;
  overflow: hidden;
  padding: 12px 0;
}

.ticker-track {
  display: flex;
  gap: var(--space-6);
  animation: ticker-scroll 25s linear infinite;
  width: max-content;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  white-space: nowrap;
  font-size: var(--text-sm);
  font-weight: 600;
  opacity: 0.9;
}

.ticker-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  opacity: 0.8;
}

.ticker-separator {
  width: 6px;
  height: 6px;
  background: oklch(100% 0 0 / 0.4);
  border-radius: 50%;
  flex-shrink: 0;
  margin: 0 var(--space-2);
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ═══════════════════════════════════════════
   Hero Section
   ═══════════════════════════════════════════ */
.hero {
  padding: var(--space-6) 0;
  background: var(--color-bg-warm);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
  align-items: center;
}

.hero-content {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  background: var(--color-accent-light);
  color: var(--color-accent);
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 700;
  width: fit-content;
}

.hero-title {
  font-size: var(--text-5xl);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--color-text);
}

.hero-subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  line-height: 1.7;
  max-width: 480px;
}

.hero-actions {
  display: flex;
  gap: var(--space-3);
  margin-top: var(--space-2);
}

.hero-image {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  aspect-ratio: 4/3;
  background: var(--color-primary-pale);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
}

.hero-image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--color-primary-pale), oklch(85% 0.08 200));
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.hero-image-placeholder::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 30% 40%, oklch(90% 0.06 200 / 0.6) 0%, transparent 60%),
    radial-gradient(circle at 70% 60%, oklch(85% 0.08 180 / 0.4) 0%, transparent 50%);
}

.hero-img-icon {
  font-size: 120px;
  position: relative;
  z-index: 1;
  opacity: 0.8;
}

.challenge-badge {
  position: absolute;
  bottom: var(--space-4);
  right: var(--space-4);
  background: var(--color-accent);
  color: #fff;
  padding: 12px 20px;
  border-radius: var(--radius-lg);
  font-weight: 700;
  font-size: var(--text-sm);
  text-align: center;
  box-shadow: var(--shadow-md);
}
.challenge-badge span {
  display: block;
  font-size: var(--text-2xl);
  font-weight: 800;
}

/* ═══════════════════════════════════════════
   Content Grid (Trending + Newsletter)
   ═══════════════════════════════════════════ */
.content-section {
  padding: var(--space-7) 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: var(--space-6);
}

/* Trending */
.trending-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
}

.trending-title {
  font-size: var(--text-xl);
  font-weight: 700;
  margin-bottom: var(--space-4);
  color: var(--color-text);
}

.trending-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.trending-item {
  display: flex;
  gap: var(--space-3);
  padding: var(--space-3);
  border-radius: var(--radius-md);
  transition: background var(--duration-fast) var(--ease-out);
  border: 1px solid transparent;
}
.trending-item:hover {
  background: var(--color-bg-warm);
  border-color: var(--color-border-light);
}

.trending-item-num {
  font-size: var(--text-2xl);
  font-weight: 800;
  color: var(--color-primary-light);
  line-height: 1;
  min-width: 32px;
}

.trending-item-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.trending-item-category {
  font-size: var(--text-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-primary);
}

.trending-item-title {
  font-size: var(--text-base);
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
}
.trending-item:hover .trending-item-title {
  color: var(--color-primary);
}

/* Newsletter CTA Card */
.newsletter-card {
  background: linear-gradient(145deg, var(--color-primary), oklch(48% 0.10 210));
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  color: #fff;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.newsletter-card-icon {
  width: 48px;
  height: 48px;
  background: oklch(100% 0 0 / 0.15);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: var(--space-4);
}

.newsletter-card h3 {
  font-size: var(--text-2xl);
  font-weight: 700;
  margin-bottom: var(--space-2);
  line-height: 1.2;
}

.newsletter-card p {
  font-size: var(--text-sm);
  opacity: 0.85;
  line-height: 1.6;
  margin-bottom: var(--space-4);
}

.newsletter-form {
  display: flex;
  gap: var(--space-2);
}

.newsletter-form input {
  flex: 1;
  padding: 12px 16px;
  border-radius: var(--radius-full);
  border: 2px solid oklch(100% 0 0 / 0.2);
  background: oklch(100% 0 0 / 0.1);
  color: #fff;
  font-size: var(--text-sm);
  outline: none;
  transition: border-color var(--duration-fast) var(--ease-out);
}
.newsletter-form input::placeholder {
  color: oklch(100% 0 0 / 0.5);
}
.newsletter-form input:focus {
  border-color: oklch(100% 0 0 / 0.5);
}

.newsletter-form .btn {
  background: #fff;
  color: var(--color-primary);
  font-weight: 700;
}
.newsletter-form .btn:hover {
  background: var(--color-bg-warm);
  color: var(--color-primary-hover);
  transform: none;
  box-shadow: none;
}

.newsletter-privacy {
  font-size: var(--text-xs);
  opacity: 0.6;
  margin-top: var(--space-2);
}

/* ═══════════════════════════════════════════
   Health Topics Carousel
   ═══════════════════════════════════════════ */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-5);
}

.section-header-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.carousel-wrapper {
  position: relative;
}

.carousel-viewport {
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.carousel-track {
  display: flex;
  gap: var(--space-4);
  transition: transform var(--duration-slow) var(--ease-in-out);
}

.topic-card {
  flex: 0 0 calc((100% - 48px) / 4);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-5) var(--space-3);
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  transition: all var(--duration-fast) var(--ease-out);
  cursor: pointer;
}
.topic-card:hover {
  border-color: var(--color-primary-light);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.topic-card-image {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: var(--color-primary-pale);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 42px;
  overflow: hidden;
}

.topic-card-label {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  text-align: center;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: var(--color-text);
  z-index: 10;
  transition: all var(--duration-fast) var(--ease-out);
}
.carousel-btn:hover {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}
.carousel-btn--prev { left: -18px; }
.carousel-btn--next { right: -18px; }

/* ═══════════════════════════════════════════
   Health Tools
   ═══════════════════════════════════════════ */
.tools-section {
  padding: var(--space-7) 0;
  background: var(--color-bg-warm);
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-5);
}

.tools-card {
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  border: 1px solid var(--color-border-light);
}

.tools-card h3 {
  font-size: var(--text-xl);
  font-weight: 700;
  margin-bottom: var(--space-2);
  color: var(--color-text);
}

.tools-card > p {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: var(--space-4);
}

.tool-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.tool-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3);
  border-radius: var(--radius-md);
  transition: background var(--duration-fast) var(--ease-out);
}
.tool-item:hover {
  background: var(--color-bg-cool);
}

.tool-item-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--color-primary-pale);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}

.tool-item-info h4 {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 2px;
}
.tool-item-info p {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  line-height: 1.4;
}

.tools-card-cta {
  margin-top: var(--space-4);
}

/* ═══════════════════════════════════════════
   Recommended Reads — Tabs
   ═══════════════════════════════════════════ */
.reads-section {
  padding: var(--space-7) 0;
}

.tabs-nav {
  display: flex;
  gap: var(--space-1);
  margin-bottom: var(--space-5);
  flex-wrap: wrap;
  border-bottom: 1px solid var(--color-border-light);
  padding-bottom: 2px;
}

.tab-btn {
  padding: 10px 20px;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-secondary);
  border-radius: var(--radius-full);
  transition: all var(--duration-fast) var(--ease-out);
  position: relative;
}
.tab-btn:hover {
  color: var(--color-primary);
  background: var(--color-primary-pale);
}
.tab-btn.active {
  color: var(--color-primary);
  background: var(--color-primary-pale);
}

.articles-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
  transition: opacity var(--duration-normal) var(--ease-out);
}

.article-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--duration-fast) var(--ease-out);
}
.article-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
  border-color: var(--color-primary-light);
}

.article-card-image {
  aspect-ratio: 16/10;
  background: var(--color-primary-pale);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}

.article-card-body {
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.article-card-category {
  font-size: var(--text-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-primary);
}

.article-card-title {
  font-size: var(--text-lg);
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text);
}
.article-card:hover .article-card-title {
  color: var(--color-primary);
}

.article-card-meta {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  margin-top: auto;
}

/* ═══════════════════════════════════════════
   Trust Pillars
   ═══════════════════════════════════════════ */
.trust-section {
  padding: var(--space-7) 0;
  background: var(--color-bg-cool);
}

.trust-header {
  text-align: center;
  margin-bottom: var(--space-6);
}

.trust-header .section-heading {
  max-width: 600px;
  margin: 0 auto;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

.trust-pillar {
  text-align: center;
  padding: var(--space-5) var(--space-4);
  background: var(--color-bg);
  border-radius: var(--radius-lg);
  border: 1px solid transparent;
  transition: all var(--duration-fast) var(--ease-out);
}
.trust-pillar:hover {
  border-color: var(--color-primary-light);
  box-shadow: var(--shadow-md);
}

.trust-pillar-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--color-primary-pale);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  margin: 0 auto var(--space-4);
}

.trust-pillar h3 {
  font-size: var(--text-lg);
  font-weight: 700;
  margin-bottom: var(--space-2);
  color: var(--color-text);
}

.trust-pillar p {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  line-height: 1.6;
}

/* ═══════════════════════════════════════════
   Featured Programs
   ═══════════════════════════════════════════ */
.programs-section {
  padding: var(--space-7) 0;
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

.program-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--duration-fast) var(--ease-out);
}
.program-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
  border-color: var(--color-primary-light);
}

.program-card-image {
  aspect-ratio: 3/2;
  background: var(--color-primary-pale);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}

.program-card-body {
  padding: var(--space-4);
}

.program-card-body h4 {
  font-size: var(--text-base);
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.3;
}
.program-card:hover .program-card-body h4 {
  color: var(--color-primary);
}

/* ═══════════════════════════════════════════
   Latest Videos
   ═══════════════════════════════════════════ */
.videos-section {
  padding: var(--space-7) 0;
  background: var(--color-bg-warm);
}

.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

.video-card {
  background: var(--color-bg);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--duration-fast) var(--ease-out);
}
.video-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
  border-color: var(--color-primary-light);
}

.video-card-thumb {
  aspect-ratio: 16/9;
  background: var(--color-primary-pale);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 40px;
}

.video-play-btn {
  position: absolute;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: oklch(0% 0 0 / 0.65);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 22px;
  transition: all var(--duration-fast) var(--ease-out);
}
.video-card:hover .video-play-btn {
  background: var(--color-primary);
  transform: scale(1.1);
}

.video-card-body {
  padding: var(--space-4);
}
.video-card-body h4 {
  font-size: var(--text-base);
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
}
.video-card:hover .video-card-body h4 {
  color: var(--color-primary);
}

/* ═══════════════════════════════════════════
   Footer
   ═══════════════════════════════════════════ */
.site-footer {
  background: var(--color-text);
  color: oklch(80% 0.01 260);
  padding: var(--space-7) 0 var(--space-5);
}

.footer-newsletter {
