  line-height: 1.6;
  color: oklch(70% 0.01 260);
  margin-top: var(--space-3);
  max-width: 280px;
}

.footer-col h4 {
  font-size: var(--text-sm);
  font-weight: 700;
  color: #fff;
  margin-bottom: var(--space-3);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.footer-links {
